VALUES ('9e803660-d390-43c6-83a6-b548927aa493', '4767cff6-b21d-4829-a4c8-3a81241d2577', 'nsclc', 'Jinhong Zhu is a rising Lung Cancer investigator at Harbin Medical University with 13 years of career experience. The strongest signal is publication output growth. Between Aug 2021 – Jul 2026, Zhu produced 10 publications, up from 6 in Aug 2016 – Jul 2021, a gain of four papers across windows. Notably, senior-author share increased between the Aug 2016 – Jul 2021 and Aug 2021 – Jul 2026 windows, indicating a shift toward independent scientific leadership. Collaborator count moved from 23 (Aug 2016 – Jul 2021) to 21 (Aug 2021 – Jul 2026), remaining stable. A transition into consistently senior-authored, multi-site Lung Cancer studies would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-19 16:46:35.792309+00:00', 'Publication output rose from 6 to 10 papers alongside a growing senior-author share across the two windows.', 'Early relationship-building focused on senior-authored work, given rising independence but limited current citation visibility.', 'early', ARRAY['Citation volume declined by 197 between the two windows, suggesting limited downstream engagement with recent output so far.']::text[], '3ee9299d-64c2-48bd-afd7-6af65b59a6f4', 'rising_star')
ON CONFLICT (id) DO NOTHING;

INSERT INTO hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort)
VALUES ('a0f563ef-814f-4683-9322-21852edb056a', 'c03fce61-b110-4b57-b9ae-ad05cee20d23', 'nsclc', 'Lucheng Zhu is a rising Lung Cancer investigator at Hangzhou Cancer Hospital with 13 years of career experience. Publication output held steady, with 11 papers in Aug 2016–Jul 2021 and 10 papers in Aug 2021–Jul 2026, while senior-authored work appears in the recent window but was absent in the early window — a meaningful shift in scientific responsibility. The strongest signal is authorship evolution. Senior-authored output emerging in Aug 2021–Jul 2026 where none existed in Aug 2016–Jul 2021 indicates a transition from contributor to independent investigator. Collaborators narrowed from 53 in Aug 2016–Jul 2021 to 24 in Aug 2021–Jul 2026, suggesting a more focused research network. A first senior-authored publication in a high-impact Lung Cancer journal would represent the next meaningful milestone.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-19 16:45:26.977641+00:00', 'Senior-authored output has emerged in Aug 2021–Jul 2026 where none existed previously.', 'Initiate early relationship-building now, ahead of anticipated senior-authored publications in high-impact Lung Cancer venues.', 'early', ARRAY['Citation volume declined over the two windows, and the collaborator network contracted from 53 to 24, limiting current external visibility.']::text[], '3ee9299d-64c2-48bd-afd7-6af65b59a6f4', 'rising_star')
ON CONFLICT (id) DO NOTHING;

INSERT INTO hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort)
VALUES ('8f6c2771-9552-4f3e-b66a-25c09bb098d0', '9470c4ea-e389-4c3b-97e9-ad6cacd65752', 'nsclc', 'Zhengfei Zhu is a rising Lung Cancer investigator at Shanghai Medical College of Fudan University, now 13 years into an active research career. The strongest signal is publication output growth. Between Aug 2021 – Jul 2026, Zhu produced 32 papers, up from 25 in Aug 2016 – Jul 2021, while senior-author share increased between the two windows, indicating a shift toward independent scientific leadership. Collaborator reach expanded from 178 (Aug 2016 – Jul 2021) to 316 (Aug 2021 – Jul 2026), nearly doubling the network in a single window. A transition into first or corresponding authorship on a high-impact Lung Cancer trial publication would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-19 16:42:58.139622+00:00', 'Collaborator network nearly doubled to 316 (Aug 2021 – Jul 2026) alongside rising senior-author share.', 'Engage now around expanding collaborator network to establish early relationship before influence broadens further.', 'early', ARRAY['Citation volume declined by 613 between the two windows, suggesting output growth has not yet translated into downstream scientific impact.']::text[], '3ee9299d-64c2-48bd-afd7-6af65b59a6f4', 'rising_star')
ON CONFLICT (id) DO NOTHING;

INSERT INTO hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort)
VALUES ('b1f1430c-fa31-4b46-b743-735979376490', '00c93561-f7bc-4090-adbf-24b81dc105c2', 'nsclc', 'Daiying Zuo is a rising Lung Cancer investigator at Shenyang Pharmaceutical University with 15 years of research experience. Publication output grew from 6 papers (Aug 2016–Jul 2021) to 8 papers (Aug 2021–Jul 2026), while the collaborator network expanded from 21 to 26 individuals across the same windows. The strongest signal is authorship positioning. Between Aug 2016–Jul 2021 and Aug 2021–Jul 2026, Zuo''s senior-author share increased, indicating a shift toward independent scientific leadership. A first high-profile senior-authored publication in a major Lung Cancer journal would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-19 16:47:31.444923+00:00', 'Senior-author share is rising alongside a growing collaborator network of 26 in Aug 2021–Jul 2026.', 'Engage now around the expanding collaborator network to establish visibility ahead of anticipated senior-authored output.', 'early', ARRAY['Citation volume declined by 106 between the two windows, suggesting limited downstream impact of recent output so far.']::text[], '3ee9299d-64c2-48bd-afd7-6af65b59a6f4', 'rising_star')
ON CONFLICT (id) DO NOTHING;

